void go(std::vector<int>& xs, int k, std::vector<std::vector<int>>& out) {
    if (k == static_cast<int>(xs.size())) {
        out.push_back(xs);
        return;
    }
    for (int i = k; i < static_cast<int>(xs.size()); ++i) {
        std::swap(xs[static_cast<std::size_t>(k)], xs[static_cast<std::size_t>(i)]);
        go(xs, k + 1, out);
        std::swap(xs[static_cast<std::size_t>(k)], xs[static_cast<std::size_t>(i)]);
    }
}

