int search(const std::vector<int>& xs, int target) {
    int lo = 0, hi = static_cast<int>(xs.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (xs[static_cast<std::size_t>(mid)] == target) return mid;
        if (xs[static_cast<std::size_t>(mid)] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

