    std::vector<std::vector<std::pair<int, int>>> adj{{{1, 1}, {2, 4}}, {{2, 2}, {3, 6}}, {{3, 3}}, {}};
    auto dist = dijkstra(adj, 0);
    return static_cast<int>(dist[3]);
}

