std::vector<int> top_k(std::vector<int> xs, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<>> heap;
    for (int x : xs) {
        heap.push(x);
        if (static_cast<int>(heap.size()) > k) heap.pop();
    }
    std::vector<int> out;
    while (!heap.empty()) {
        out.push_back(heap.top());
        heap.pop();
    }
    return out;
}

