};

std::unique_ptr<ListNode> reverse(std::unique_ptr<ListNode> head) {
    std::unique_ptr<ListNode> prev;
    while (head) {
        auto next = std::move(head->next);
        head->next = std::move(prev);
        prev = std::move(head);
        head = std::move(next);
    }
    return prev;
}

