int count_subarrays_summing_to(const std::vector<int>& xs, int target) {
    std::unordered_map<long long, int> seen{{0, 1}};
    long long running = 0;
    int total = 0;
    for (int x : xs) {
        running += x;
        auto it = seen.find(running - target);
        if (it != seen.end()) total += it->second;
        ++seen[running];
    }
    return total;
}

